 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,
 conditions=conditions or {'方向':'最も不適切なもの。','対象':'地球表層の自然水・岩石・元素循環。各肢の条件は独自要約として保持。'},
 choices={str(i):dict(value=v,verdict=d,reason=w) for i,(v,d,w) in enumerate(zip(vals,verdicts,reasons),1)},
 figures='設問幹・全5肢・否定・数字・単位・化学記号を原典画像で照合。設問固有図なし。',
 ambiguity=ambiguity,evidence=ini[q]['source_images_viewed'],core_concept=core,
 required_knowledge=core+'。'+solution,solution=solution,independent_answer=ini[q]['independent_answer'],
 independent_solution_note='S7_021_independent_answers.jsonへ公式参照前の判断を保存。'+ini[q]['reason']+' 後続の一次検証は初回を上書きせず、適用条件・疑義を追加する。',
 answer_reason=solution,learning_points='物質の貯留量・輸送速度・化学形態を分け、系の境界と反応の前提を確かめる。'+core+'を収支・平衡・反応速度のどのモデルで扱うか選ぶ。',
 theory_references=['theory:geochemistry:'+s for s in labels],discipline_id='earth_chem',concept_id=concept,
 classification_reason='原典全肢の中心は'+core+'であり、単なる元素名や一肢の帯水層から主分類を決めない。地球表層の化学組成・循環へ主分類を合わせる。',
 calculation=str(calc).lower(),figure='false',law=str(law).lower(),
 evaluation=dict(knowledge_novelty='3',reasoning_steps='2',calculation_load='1' if calc else '0',figure_reading='0',difficulty='3',difficulty_reason='物理専攻読者が水質・地球化学の新規概念を学び、複数の物質形態・条件を区別して判断する。単位・指数の短い比較を含むが数学的負荷は小さい。'),
 citations=cites,foundationality='high',transferability='high'))
